/// Overlay writes staged by a transform and committed only after every local validation
/// has accepted the pass. The cache-state CAS serializes competing speculative renders.
#[derive(Debug, Default)]
pub struct TransformOverlayBatch<'a> {
    pub max_seen_ordinal: Option<u64>,
    pub tag_mints: &'a [McTagRow],
    pub temporal_marks: &'a [TemporalMarkInput],
    /// Replace existing temporal bytes during a consumed renderer transition. Ordinary
    /// first-sight decisions remain insert-only and frontier-gated.
    pub rewrite_temporal_marks: bool,
    pub user_hint: Option<&'a UserHintDecisionInput>,
    pub channel1_append: Option<&'a Channel1AppendRow>,
    pub created_at_ms: i64,
}

impl TransformOverlayBatch<'_> {
    pub fn is_empty(&self) -> bool {
        self.max_seen_ordinal.is_none()
            && self.tag_mints.is_empty()
            && self.temporal_marks.is_empty()
            && !self.rewrite_temporal_marks
            && self.user_hint.is_none()
            && self.channel1_append.is_none()
    }
}

/// Whether a commit may store an empty frozen-unit list over a session that has units.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum FrozenClear {
    /// Refuse: an empty list is more likely a state that was never loaded than a
    /// deliberate clear.
    #[default]
    Refuse,
    /// The caller really is resetting the list.
    Explicit,
}

/// How a transform commit writes the split chunk and section rows.
#[derive(Debug, Clone, Copy, Default)]
pub struct SectionsCommit<'a> {
    /// The base the pass loaded ([`LoadedState::sections`]). With it the commit writes only
    /// the rows whose bytes differ from it, rewrites in full any section it discarded, and
    /// refuses with a CAS conflict if another codec writer advanced the sections version
    /// since the load. Without it the commit decodes the stored rows inside its own
    /// transaction and diffs against those.
    pub base: Option<&'a SectionsBase>,
    /// `row_version` steps the pass adopted from meta-only writers after loading `base`.
    /// The commit checks `expected == base.row_version + meta_only_steps`, so a pass cannot
    /// commit chunks diffed against a base from some other commit.
    pub meta_only_steps: u64,
    pub frozen_clear: FrozenClear,
}

impl<'a> SectionsCommit<'a> {
    /// Diff against the base a load returned.
    pub fn over(base: Option<&'a SectionsBase>) -> Self {
        SectionsCommit {
            base,
            ..SectionsCommit::default()
        }
    }
}

pub struct TransformCommit<'a> {
    pub expected: Option<u64>,
    pub core: &'a CoreState,
    pub meta: &'a ModuleMeta,
    pub sections: SectionsCommit<'a>,
    pub consumed_drop_ids: &'a [i64],
    pub first_applied_command_ids: &'a [String],
    pub memory_revision: Option<&'a MemoryRevision>,
    /// Highest compartment sequence observed while composing a bust. The fenced commit
    /// re-reads this scalar so a publication interleaved between signal read and commit
    /// cannot be hidden behind the older rendered m1 bytes.
    pub compartment_max_seq: Option<i64>,
    /// Authenticated filesystem root observed by the transform that owns this cache commit.
    pub project_root: Option<&'a str>,
    /// Serialized first-divergence attribution to store with the accepted pass.
    pub first_divergence: Option<&'a str>,
    /// Scheduler arm and updated drain-latch state for a real accepted transform pass.
    /// Maintenance callers that reuse this transaction leave it absent.
    pub scheduler_observation: Option<&'a PassSchedulerObservation>,
    /// Sender clock and exact full-array identity already carried on the transform request.
    pub scheduler_request_observed_at_ms: Option<u64>,
    pub scheduler_full_array_fingerprint: Option<&'a str>,
    /// Eligible supersession tool arcs counted when an open ride gate runs selection. Missing
    /// means selection did not run; zero means it ran and found none.
    pub scheduler_eligible_supersession_count: Option<u64>,
    pub scheduler_withheld_by_tag_window: Option<u64>,
    pub scheduler_withheld_by_exempt_message: Option<u64>,
    pub scheduler_applied_supersession_count: Option<u64>,
    /// Whether this pass added a previously-unfrozen reduction to the served output.
    pub scheduler_applied_reductions: bool,
    pub overlays: TransformOverlayBatch<'a>,
}

