/// Outcome of the fenced commit txn: either the new row_version, or a CAS conflict
/// carrying the version observed on disk. Modeled as a return value (not an error)
/// so a conflicting pass commits an empty txn and the caller re-loads cleanly.
enum MemoryMutationOutcome {
    NotFound,
    Applied(Box<Option<StoredMemoryFull>>),
    Duplicate(i64),
}

enum CommitOutcome {
    Committed(u64),
    CasConflict(u64),
    UnhydratedBlockIdentities(usize),
    FrozenClearRefused(u64),
}

enum PublishTxnOutcome {
    Committed(HistorianPublishResult),
    CasConflict {
        found: u64,
        reason: Option<String>,
    },
    FenceRejected(String),
    CompartmentOverlap {
        existing_sequence: i64,
        incoming_start_message: i64,
        incoming_end_message: i64,
    },
    StateMismatch(Box<HistorianDurableState>),
    InvalidState(String),
    Serde(String),
}

enum AppendCompartmentsTxnOutcome {
    /// The rows landed from `first_sequence` on, as the append transaction assigned them.
    Appended { first_sequence: i64 },
    Overlap {
        existing_sequence: i64,
        incoming_start_message: i64,
        incoming_end_message: i64,
    },
}

