    #[test]
    fn zero_target_append_records_ledger_row_with_no_targets_disposition() {
        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open_for_test(&descriptor(dir.path())).unwrap();

        // Zero targets: the ledger row is recorded with disposition='no_targets'
        // so a retry of the same command_id still dedupes.
        let outcome = store
            .append_pending_agent_drops_with_command("ses", Some("cmd-zero"), &[], 1, true)
            .unwrap();
        assert_eq!(
            outcome,
            AppendOutcome {
                queued: 0,
                duplicate: false,
                disposition: Some("no_targets".to_string()),
            }
        );
        assert!(store.load_pending_agent_drops("ses").unwrap().is_empty());

        // Retry of the same command_id must still dedupe (idempotency).
        let retry = store
            .append_pending_agent_drops_with_command("ses", Some("cmd-zero"), &[], 2, true)
            .unwrap();
        assert_eq!(
            retry,
            AppendOutcome {
                queued: 0,
                duplicate: true,
                disposition: None,
            }
        );

        // A normal command with actual targets still queues pending drops and does not
        // set any disposition — the no_targets path only applies when canonicalization
        // resolved zero block_ids.
        let normal = store
            .append_pending_agent_drops_with_command(
                "ses",
                Some("cmd-normal"),
                &["a#0".to_string()],
                3,
                false,
            )
            .unwrap();
        assert_eq!(
            normal,
            AppendOutcome {
                queued: 1,
                duplicate: false,
                disposition: None,
            }
        );
        assert_eq!(store.load_pending_agent_drops("ses").unwrap().len(), 1);

        // The diagnostic ledger must distinguish the terminal no-target result from work
        // that is still pending; a constant disposition would make incident reads misleading.
        assert_eq!(
            command_ledger_rows(&store, "ses"),
            vec![
                ("cmd-zero".to_string(), Some("no_targets".to_string())),
                ("cmd-normal".to_string(), None),
            ]
        );
    }

    #[test]
    fn session_status_tag_count_includes_all_operational_tag_states_and_pages() {
        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open_for_test(&descriptor(dir.path())).unwrap();
        let session_id = "status-tag-total";
        let tags = (1..=6)
            .map(|ordinal| TagMintInput {
                block_id: format!("m{ordinal}#0"),
                kind: "message".to_string(),
                token_count: ordinal,
                source_bytes: format!("message {ordinal}").into_bytes(),
            })
            .collect::<Vec<_>>();
        store.mint_or_get_tags(session_id, &tags, 100).unwrap();
        store
            .mint_or_get_tags(
                "another-session",
                &[TagMintInput {
                    block_id: "m1#0".to_string(),
                    kind: "message".to_string(),
                    token_count: 1,
                    source_bytes: b"other".to_vec(),
                }],
                100,
            )
            .unwrap();
        store
            .replace_compartments(
                session_id,
                &[StoredCompartment {
                    sequence: 1,
                    start_message: 1,
                    end_message: 2,
                    end_message_id: "m2#0".to_string(),
                    title: "frozen prefix".to_string(),
                    content: "prefix".to_string(),
                    importance: 50,
                    ..Default::default()
                }],
            )
            .unwrap();
        store
            .append_pending_agent_drops(session_id, &["m3#0".to_string(), "m4#0".to_string()], 200)
            .unwrap();
        let core = CoreState {
            boundary_id: "m2#0".to_string(),
            ..Default::default()
        };
        let meta = ModuleMeta {
            coverage_ordinal: Some(4),
            ..Default::default()
        };
        store.commit(session_id, None, &core, &meta).unwrap();

        // The compartment covers m1-m2, queued drops cover m3-m4, and m5-m6 remain active.
        // The status total must cross both the durable coverage boundary and the requested page.
        let snapshot = store.load_session_status_snapshot(session_id).unwrap();
        assert_eq!(snapshot.loaded.meta.coverage_ordinal, Some(4));
        assert_eq!(snapshot.compartment_count, 1);
        assert_eq!(snapshot.pending_drop_count, 2);
        assert_eq!(snapshot.tag_count, 6);
        assert_eq!(
            snapshot.tag_count,
            store.load_tags_for_session(session_id).unwrap().len()
        );
    }

