    #[test]
    fn retained_transform_hot_path_queries_are_index_or_rowid_lookups() {
        fn plan_details(store: &McStore, sql: &str) -> Vec<String> {
            store
                .inner
                .with_conn(|conn| {
                    let mut statement = conn.prepare(&format!("EXPLAIN QUERY PLAN {sql}"))?;
                    let rows = statement
                        .query_map([], |row| row.get::<_, String>(3))?
                        .collect::<Result<Vec<_>, _>>()?;
                    Ok(rows)
                })
                .unwrap()
        }

        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open_for_test(&descriptor(dir.path())).unwrap();
        let queries = [
            (
                "handler/cache state",
                "SELECT row_version, core_state, meta FROM mc_cache_state \
                 WHERE session_id = 'plan-session'",
            ),
            (
                "tag generation",
                "SELECT generation, tag_count, max_tag_number FROM mc_tag_cache_generations \
                 WHERE session_id = 'plan-session'",
            ),
            (
                "tag baseline",
                "SELECT tag_number, block_id, kind, token_count, created_at_ms, source_bytes \
                 FROM mc_tags WHERE session_id = 'plan-session' ORDER BY tag_number ASC",
            ),
            (
                "tag append delta",
                "SELECT tag_number, block_id, kind, token_count, created_at_ms, source_bytes \
                 FROM mc_tags WHERE session_id = 'plan-session' AND tag_number > 7 \
                 ORDER BY tag_number ASC",
            ),
            (
                "temporal overlays",
                "SELECT block_id, marker_text, created_at FROM mc_temporal_marks \
                 WHERE session_id = 'plan-session' ORDER BY created_at ASC, block_id ASC",
            ),
            (
                "user hints",
                "SELECT block_id, hint_text, created_at FROM mc_user_hints \
                 WHERE session_id = 'plan-session' ORDER BY created_at ASC, block_id ASC",
            ),
            (
                "channel-1 appends",
                "SELECT block_id, reminder_text, fired_at_ms FROM mc_channel1_appends \
                 WHERE session_id = 'plan-session' ORDER BY fired_at_ms ASC, block_id ASC",
            ),
            (
                "overlay frontier",
                "SELECT max_seen_ordinal FROM mc_overlay_frontiers \
                 WHERE session_id = 'plan-session'",
            ),
            (
                "pending drops",
                "SELECT p.id, p.target_id, p.queued_at, p.command_id, l.first_applied_at_ms \
                 FROM pending_agent_drops p LEFT JOIN mc_reduce_command_ledger l \
                   ON l.session_id = p.session_id AND l.command_id = p.command_id \
                 WHERE p.session_id = 'plan-session' ORDER BY p.queued_at ASC, p.id ASC",
            ),
            (
                "project mural",
                "SELECT data_url, content_hash FROM mc_project_mural_artifacts \
                 WHERE project_path = 'git:plan'",
            ),
            (
                "block identities",
                "SELECT mid, identities FROM mc_block_identities \
                 WHERE session_id = 'plan-session'",
            ),
            (
                "block identity fence",
                "SELECT identities FROM mc_block_identities \
                 WHERE session_id = 'plan-session' AND mid = 'm1'",
            ),
            (
                "served output fingerprints",
                "SELECT block_id, content_hash, serialized_len FROM mc_served_output_fingerprints \
                 WHERE session_id = 'plan-session' ORDER BY position ASC",
            ),
            (
                "cache state digest",
                "SELECT row_version, row_state_fingerprint FROM mc_cache_state_digest \
                 WHERE session_id = 'plan-session'",
            ),
        ];

        for (name, sql) in queries {
            let details = plan_details(&store, sql);
            assert!(
                details.iter().all(|detail| {
                    let upper = detail.to_ascii_uppercase();
                    !upper.starts_with("SCAN ")
                        || upper.contains("USING INDEX")
                        || upper.contains("USING COVERING INDEX")
                }),
                "{name} must not perform an unindexed table scan: {details:?}"
            );
            assert!(
                details.iter().any(|detail| {
                    let upper = detail.to_ascii_uppercase();
                    upper.starts_with("SEARCH ")
                        || upper.contains("USING INDEX")
                        || upper.contains("USING COVERING INDEX")
                }),
                "{name} must use an index or rowid lookup: {details:?}"
            );
            assert!(
                !details
                    .iter()
                    .any(|detail| detail.contains("USE TEMP B-TREE")),
                "{name} must not create a temporary sort index: {details:?}"
            );
        }
    }

    #[test]
    fn m1_revision_snapshot_matches_individual_watermarks() {
        let dir = tempfile::tempdir().unwrap();
        let store = McStore::open_for_test(&descriptor(dir.path())).unwrap();
        let own = "git:m1-own";
        let foreign = "git:m1-foreign";
        store
            .seed_workspace_member("m1-workspace", own, "[\"CONSTRAINTS\"]")
            .unwrap();
        store
            .seed_workspace_member("m1-workspace", foreign, "[\"CONSTRAINTS\"]")
            .unwrap();
        store.seed_memory(7, own, "CONSTRAINTS", "own", 50).unwrap();
        store
            .seed_memory(11, foreign, "CONSTRAINTS", "foreign", 50)
            .unwrap();
        store
            .set_memory_sharing_for_test(11, "project", true)
            .unwrap();
        store
            .seed_mutation(own, "update", 7, "own updated")
            .unwrap();
        store
            .seed_mutation(foreign, "update", 11, "foreign updated")
            .unwrap();
        store
            .replace_compartments(
                "m1-session",
                &[StoredCompartment {
                    sequence: 4,
                    start_message: 1,
                    end_message: 9,
                    ..Default::default()
                }],
            )
            .unwrap();
        let note = store
            .insert_project_note(NoteWriteInput {
                project_path: own,
                route_project_root: None,
                session_id: Some("m1-session"),
                content: "m1 note",
                surface_condition: None,
                compiled_provider: None,
                compiled_config: None,
                compiled_at: None,
                compile_status: None,
                anchor_block_id: None,
                anchor_ordinal: None,
                now_ms: 1,
            })
            .unwrap();
        store
            .with_context_conn_for_test(|tx| {
                tx.execute(
                    "UPDATE notes SET updated_at = 6 WHERE id = ?1",
                    params![note.id],
                )?;
                Ok(())
            })
            .unwrap();

        let snapshot = store
            .load_m1_revision_snapshot(own, own, "m1-session", true, 0)
            .unwrap();
        let membership = snapshot.membership.clone().unwrap();
        assert_eq!(membership.union_identities, vec![foreign, own]);
        assert_eq!(membership.share_categories, vec!["CONSTRAINTS"]);
        assert_eq!(
            snapshot.max_memory_id,
            store.max_memory_id(&membership.union_identities).unwrap()
        );
        assert_eq!(
            snapshot.max_memory_mutation_id,
            store
                .max_memory_mutation_id(&membership.union_identities)
                .unwrap()
        );
        assert_eq!(
            snapshot.max_compartment_seq,
            store.max_compartment_seq("m1-session").unwrap()
        );
        assert_eq!(
            snapshot.note_status_version,
            store.max_note_status_version(own).unwrap()
        );
        assert_eq!(
            store.workspace_fingerprint_for_membership(snapshot.membership.as_ref()),
            store.workspace_fingerprint(own, 0).unwrap()
        );

        let disabled = store
            .load_m1_revision_snapshot(own, own, "m1-session", false, 0)
            .unwrap();
        assert_eq!(disabled.membership, snapshot.membership);
        assert_eq!(disabled.max_memory_id, 0);
        assert_eq!(disabled.max_memory_mutation_id, 0);
        assert_eq!(disabled.max_compartment_seq, snapshot.max_compartment_seq);
        assert_eq!(disabled.note_status_version, snapshot.note_status_version);
    }

